% =====================================================================
\chapter{Was der Körper verliert: Wärmehaushalt, Wetter und Werkstoffe}
% =====================================================================

\section{Konzept 2.1: Der Wärmehaushalt des Menschen}

\begin{konzept}{2.1 – Der Wärmehaushalt des Menschen}
\textbf{Definition.} Der Körper erzeugt Wärme durch Stoffwechsel und verliert sie über five Wege: Strahlung, Leitung, Konvektion, Verdunstung und Atmung. Eine Unterkunft wirkt, indem sie diese fünf Verlustwege drosselt.

\textbf{Dreifache Prüfung (vor der Aufnahme).}
\begin{enumerate}
  \item Quelle eins: physiologische Grundlagen der Wärmeabgabe (Lehrbuchwissen, in jedem Physiologie-Handbuch nachlesbar).
  \item Quelle zwei: Messwerte aus dem Outdoor-Bereich (Faustwerte, keine Laborbedingungen).
  \item Quelle drei: eigene Prüfhandlung – nasse Socken bei 5 Grad Außentemperatur tragen und Zeit bis zur Muskelsteifigkeit notieren (Übung C.1).
\end{enumerate}

\textbf{Dreifache Bewertung (nach bestandener Prüfung).}
\begin{enumerate}
  \item Stimmigkeit: die fünf Verlustwege erklären jede Maßnahme der Kapitel 3 bis 9.
  \item Praxistauglichkeit: jede Drosselungsmaßnahme ist ohne Werkzeug prüfbar (Faustprobe, unten).
  \item Ehrlichkeit: Werte schwanken je nach Person, Fett, Alter; alle Zahlen sind Faustwerte.
\end{enumerate}

\textbf{Grenzen.} Ohne Kalorienzufuhr sinkt die Eigenproduktion; Unterkunft ersetzt keine Nahrung. Kinder und Ältere verlieren schneller, Faustwert: doppelte Aufmerksamkeit.

\textbf{Verlustwege und Gegenmaßnahmen.}

\begin{tabular}{p{3.0cm}p{4.0cm}p{4.2cm}p{4.2cm}}
\toprule
Verlustweg & Anteil, Faustwert & Drosselung durch Kleidung & Drosselung durch Unterkunft \\
\midrule
Strahlung & hoch bei klarem Himmel & zweite Lage, reflektierende Oberfläche & Dach mit geschlossenem Innenhimmel \\
Leitung & hoch bei Kontakt kalter Fläche & dicke Sohle, Lagermatte aus Astwerk & Bettboden, min. 10 cm Luftpolster \\
Konvektion & hoch bei Wind & winddichte Außenlage & Windschutz, Tür an Luv \\
Verdunstung & hoch bei Nässe & trockene Wollsachen & Lüften ohne Auskühlen \\
Atmung & gering, fix & – & Kopf im Schlafraum bei Kälte,offen in beheizten Räumen \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Faustprobe Kältebrücke (5 Minuten).}
\begin{enumerate}
  \item Legen Sie den Handrücken auf den verdächtigen Boden, die Wand, die Naht.
  \item Zählen Sie bis 60.
  \item Kalt oder nass: Kältebrücke gefunden. Isolieren nach Kapitel 6.
  \item Warm und trocken: weiter, nächste Stelle.
\end{enumerate}
\end{konzept}

\subsection{Bausteine Wärmehaushalt}

\begin{baustein}
\merk{Der Kopf strahlt am stärksten – Mütze vor Mantel.} \\
\merk{Kalte Füße = nasse Füße oder dünner Boden; prüfe beide.} \\
\merk{Zittern ist die letzte Warnstufe – handle, rede nicht.}
\end{baustein}

\section{Konzept 2.2: Wetter lesen und Wind einschätzen}

\begin{konzept}{2.2 – Wetter lesen und Wind einschätzen}
\textbf{Definition.} Wetterablesen heißt, aus sichtbaren Zeichen (Bewölkung, Wind, Geruch, Tierverhalten) die nächsten 12 bis 24 Stunden abzuschätzen und den Bauentscheid danach zu treffen.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Verglichen mit offiziellen Vorhersagen über 30 Tage: Trefferquote notieren (Übung C.2).
  \item Geprüft gegen Barometer oder Höhenmesser, wenn vorhanden.
  \item Geprüft gegen ortskundige Aussagen, wo erreichbar.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: die Zeichenliste hat sich über den Übungszeitraum bewährt.
  \item Praxistauglichkeit: alles ohne Gerät lesbar.
  \item Ehrlichkeit: keine Vorhersage trifft sicher; der Bau muss Reserve haben (Kapitel 4).
\end{enumerate}

\textbf{Grenzen.} Ohne Gerät keine Sturmvorhersage. Bei angekündigtem Sturm (Hörbarkeit des fernen Tals) niemals Dachdecken oder Gerüstklettern.

\textbf{Zeichen-Tabelle (Faustwerte, örtlich prüfen).}

\begin{tabular}{p{4.6cm}p{5.0cm}p{5.4cm}}
\toprule
Zeichen & Deutung, Faustwert & Bauentscheid \\
\midrule
Klarer Himmel nachmittag, Wind still & Nacht kälter als tagsüber, oft Reif & Doppelte Bodenluft, Kapitel 6.1 \\
Wolkendecke abends zu & geringere Auskühlung & Einzelabdeckung reicht \\
Rauch sinkt am Morgen in die Täler & Hochdruck, stabile Tage & Bauen erlaubt \\
Ferner Donner, ohne Gewitterzelle & Sturmfront, Stunden entfernt & Gerüst sichern, keine neuen Lasten \\
Vögel niedrig, Insekten plötzlich weg & Regen nahe & Fertigstellen der Dichtungen vor dem Regen \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Fahnenprobe Windrichtung (10 Minuten).}
\begin{enumerate}
  \item Binden Sie ein 40 cm langes Band an eine 1,5 m Stange.
  \item Stecken Sie die Stange am geplanten Standort ein.
  \item Lesen Sie über 2 Minuten: Hauptrichtung und Schwankung notieren.
  \item Tür an Lee, Windschutz an Luv errichten (Kapitel 3.1).
  \item Wiederholen Sie nach 3 Stunden; bei Dreh über 90 Grad planen Sie eine zweite Öffnung.
\end{enumerate}
\end{konzept}

\section{Konzept 2.3: Werkstoffe für Unterkunft und Textil}

\begin{konzept}{2.3 – Werkstoffe für Unterkunft und Textil}
\textbf{Definition.} Fünf Werkstoffgruppen decken den Bedarf des Bandes: Holz, Erdreich, pflanzliche Faser, Tierfaser, Kunstfaser (Vorrat). Jede Gruppe hat feste Rollen; Austausch nur nach der Tabelle.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Eigener Härtetest: Zugprobe an Fasern, Regenprobe an Flächen (Übung C.3).
  \item Vergleich mit Anwendungen im Band 3 (Feuer) und Band 5 (Pflanzen).
  \item Prüfung der Verfügbarkeit in beiden Ausgangslagen, Stadt und Land.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: jede Rolle deckt eine Bauaufgabe der Kapitel 3 bis 9.
  \item Praxistauglichkeit: jede Gruppe ist ohne Spezialwerkzeug nutzbar.
  \item Ehrlichkeit: Kunstfaser zerfällt nach Jahren; Verbaukunststoff ist keine Dauerlösung.
\end{enumerate}

\textbf{Grenzen.} Ohne Säge kein Stammholz, ohne Axt kein gespaltene Bretter. Faustwert hierfür: Kapitel 4.3.

\begin{tabular}{p{2.6cm}p{4.0cm}p{4.0cm}p{4.0cm}}
\toprule
Gruppe & Rolle im Bau & Rolle in Textil & Stadtquelle \\
\midrule
Holz & Gerüst, Wand, Dachstuhl & – & Abbruchholz, Paletten, Schreinerabfälle \\
Erdreich & Grubenwand, Grassoden, Lehmfleck & – & Baustellenaushub, Gartenland \\
Pflanzliche Faser & Binden, Seile, Füllung & Kleidung, Netze & Schilf, Brennnessel, Stroh (Band 5) \\
Tierfaser & – & Wolle, Filz, Leder & Second-Hand, Fellreste \\
Kunstfaser (Vorrat) & Planen, Folienschutz & Reißverschluss, Fleece & Verbauware, Spenden, Abbruch \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Zugprobe Faser (3 Minuten).}
\begin{enumerate}
  \item Nehmen Sie 30 cm Faser, feuchten Sie die Mitte an.
  \item Ziehen Sie gleichmäßig auseinander.
  \item Reißt unter leichtem Zug: nur für Wickelbund, nicht für tragende Schnur.
  \item Hält das 3-fache eines vollen Eimers am Gewicht: tragende Schnur (Konzept 7.3).
\end{enumerate}
\end{konzept}

\subsection{Werkstoff-Grenzetablelle}

\begin{tabular}{p{4.0cm}p{11.0cm}}
\toprule
Werkstoff & Ehrliche Grenze \\
\midrule
Frisches Grünholz & Schwindet beim Trocknen; Verbindungen alle 2 Wochen nachziehen \\
Weiches Faulholz & Zerbricht ohne Vorwarnung; Fingerprobe: Stecknagel bis 1 cm tief? Verwerfen. \\
Folie, Planen & UV-spröde nach Monaten; nie als alleinige Dachhaut \\
Nass geschnittenes Stroh & fault in 3 bis 5 Tagen an der Wand; nur trocken verbauen \\
Verbau-Kunststoff & scharfkantig, splittert; handschuhepflicht bei der Bearbeitung \\
\bottomrule
\end{tabular}

\section{Kapitel-Checkliste: Wärmehaushalt, Wetter, Werkstoffe}

\begin{checkliste}
\item Ich kann die fünf Verlustwege aufzählen und je eine Gegenmaßnahme zuordnen.
\item Ich habe die Fahnenprobe am geplanten Standort ausgeführt und notiert.
\item Ich habe die Wetterzeichen-Tabelle mit örtlichen Werten abgeglichen (örtlich prüfen).
\item Jede Faser, die ich verbauen will, hat die Zugprobe bestanden.
\item Ich habe für jeden Werkstoff die ehrliche Grenze gelesen und akzeptiert.
\end{checkliste}

% =====================================================================
\chapter{Die erste Nacht: Behelfsunterkünfte}
% =====================================================================

\section{Konzept 3.1: Standortwahl in einer Stunde}

\begin{konzept}{3.1 – Standortwahl in einer Stunde}
\textbf{Definition.} Standortwahl ist das Festlegen des Schlafplatzes nach vier Kriterien: Wasser (10 Minuten Weg), Drainage, Wind, Sicherheit. Die Prüfung dauert höchstens eine Stunde.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Nach jeder Prüfung einer Kriteriumsliste: Kriterien bleiben gleich, Reihenfolge nach Situation.
  \item Probe-Nacht am Standort vor dem Bau (Übung C.4).
  \item Abgleich mit Kapitel 1 (Ethik, Gemeingut).
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: die Kriterien decken die häufigsten Fehler (Anhang B, Fehler 1 bis 8).
  \item Praxistauglichkeit: in einer Stunde ausführbar.
  \item Ehrlichkeit: kein Standort erfüllt alle Kriterien; die Tabelle zwingt zur Entscheidung.
\end{enumerate}

\textbf{Grenzen.} Ohne Ortskenntnis bleibt ein Restrisiko. Flagge: Flut, Mure, Waldbrand – bei Verdacht weichen, nicht bauen.

\begin{tabular}{p{3.0cm}p{4.6cm}p{4.6cm}}
\toprule
Kriterium & Stadtprüfung & Landprüfung \\
\midrule
Wasser & 10 min zu zugänglicher Stelle; Qualität nach Band 1 & Quelle, Bach; 30 m Abstand vom Schlafplatz (Feuchteschutz) \\
Drainage & Asphalt und Beton: Überprüfung auf Pfützenstand & Handfull Test: 20 cm graben; staubtrocken besser \\
Wind & Hauswände als Windschutz nutzen, Kanalisation vermeiden & Fahnenprobe 2.2; Kamm und Tallage meiden \\
Sicherheit & Fluchtwege: zwei Richtungen, beide breit genug & Wurfdistanz toter Bäume: 1,5-fache Stammlänge \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Standortlauf (60 Minuten).}
\begin{enumerate}
  \item Umkreis von 200 m um den Ruhebedarf abgehen; drei Kandidaten markieren.
  \item Jeden Kandidaten nach den vier Kriterien bewerten (Vorlage A.4).
  \item Höchstsumme gewinnt; bei Gleichstand entscheidet Wasser.
  \item Probe-Nacht planen (Kapitel 3.2 oder 3.3).
  \item Vor dem Bau: Rückbau-Gedanke, Kapitel 1.
\end{enumerate}
\end{konzept}

\section{Konzept 3.2: Behelfsunterkunft in der Stadt}

\begin{konzept}{3.2 – Behelfsunterkunft in der Stadt}
\textbf{Definition.} Stadtbehelf ist eine Unterkunft aus Vorrats- und Fundmaterial, errichtet in unter 6 Stunden, rückbaubar in unter 24 Stunden, ohne Werkzeug oder mit einem Werkzeug.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Aufbau in drei verschiedenen Stadtumgebungen (Park, Ruine, Innenhof).
  \item Kälteprüfung bei mindestens 0 Grad (Übung C.5).
  \item Rückbau-Zeit gestoppt; 24-Stunden-Grenze eingehalten.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Materialien sind in jeder Stadt auffindbar (Paletten, Planen, Karton).
  \item Praxistauglichkeit: ein Werkzeug genügt (Brechstange oder Beil).
  \item Ehrlichkeit: keine Winterfestigkeit; Behelf gilt für drei bis fünf Nächte.
\end{enumerate}

\textbf{Grenzen.} Ohne Isolierschicht (Kapitel 6) ist der Behelf nur ein Wind- und Regenschutz. Rückbau-Pflicht nach Kapitel 1 gilt uneingeschränkt.

\textbf{Materialliste Stadt-Behelf.}

\begin{tabular}{p{4.6cm}p{3.2cm}p{4.2cm}}
\toprule
Material & Menge, Faustwert & Quelle \\
\midrule
Holzpalette, unbeschädigt & 2 Stück & Lieferräume, Märkte \\
Plane oder schwere Folie & 4 m\textsuperscript{2} & Baustellen, Verpackung \\
Kartons, dick, trocken & 6 Stück & Einzelhandel \\
Schnur, reißfest & 20 m & überall \\
Steine oder Ziegel & 10 Stück & Brachfläche \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Aufbau (6 Stunden, zwei Personen).}
\begin{enumerate}
  \item Palette als Boden auslegen; Unterseite nach unten, auf vier Ziegel oder Steine stellen (10 cm Luft nach Kapitel 2.1).
  \item Zweite Palette senkrecht als Rückwand an eine Mauer lehnen, mit Schnur an einer Hakenlage gesichert.
  \item Plane über beide Paletten ziehen; First zur Mauer, unten min. 10 cm Überstand über die Rückwand.
  \item Kartonlagen dreilagig: innen glatt, Mitte geknüllt, außen glatt.
  \item Plane mit Steinen am Boden beschweren, je 50 cm ein Stein.
  \item Türseite offen lassen, aber eine Notanker-Kartonscheibe bereithalten.
  \item Innentemperatur mit Handrücken prüfen; Kältebrücken nach 2.1 Faustprobe suchen.
  \item Rückbau-Plan notieren (Vorlage A.5); nach spätestens fünf Nächten umrüsten auf Kapitel 4.
\end{enumerate}
\end{konzept}

\begin{warnbox}
\textbf{Kohlenmonoxid in geschlossenen Behelfen.} Kochen, Wärmen oder Kerzen in einem geschlossenen Stadtbehelf aus Planen und Karton können Kohlenmonoxid erzeugen – geruchlos, ohne Vorwarnung, tödlich overnight. Jede Flamme braucht eine Öffnung von mindestens 200 cm\textsuperscript{2} Richtung Frischluft, dauerhaft offen, auch bei Frost. Symptome einer beginnenden Vergiftung: Kopfschmerz, Übelkeit, Schwindel – sofort ins Freie und lüften. Nie in einem Behelf schlafen, in dem geglüht oder gekocht wurde, solange Glut oder Dampf vorhanden ist.
\end{warnbox}

\section{Konzept 3.3: Behelfsunterkunft auf dem Land}

\begin{konzept}{3.3 – Behelfsunterkunft auf dem Land}
\textbf{Definition.} Landbehelf ist eine Unterkunft aus Naturmaterial (Astwerk, Gras, Erde), errichtet in unter 10 Stunden, primär gegen Wind und Bodenkälte.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Aufbau in drei Geländearten (Waldrand, Feld, Hanglage).
  \item Kälteprüfung bei 0 Grad und bei Nieselregen.
  \item Prüfung des Materialverbrauchs gegen Band-5-Regeln (Totholz, Konzept 1.1).
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Material ohne Werkzeug außer Beil oder Säge beschaffbar.
  \item Praxistauglichkeit: Aufbau ohne Lehre, aus Erinnerung.
  \item Ehrlichkeit: Regen ist der Schwachpunkt; Dauerregen über 24 Stunden erfordert Kapitel 4 oder 5.
\end{enumerate}

\textbf{Grenzen.} Feuchtwetter über Tage lässt jede Astwerkdecke durchsickern. Keine Feuerstelle innen; Feuer nach Band 3 in Gruben vor der Tür.

\textbf{Anleitung: Lehmgroßhütte, einfacher Typ (10 Stunden, zwei Personen).}
\begin{enumerate}
  \item Suchen Sie eine senkrechte natürliche Stütze: Felsblock, Baumstumpf, Böschungskante.
  \item Legen Sie eine Liegefläche fest: 180 cm mal 80 cm, gemessen mit Schnur.
  \item Stellen Sie einen First aus einem Ast von 200 cm Länge, an beiden Enden gegabelt unterstützt (Zapfenlager, 4.1).
  \item Legen Sie Seitenäste beidseitig vom First herab, Abstand 15 cm, bis zur Bodenlinie.
  \item Flechten Sie Queräste horizontal ein, je drei Lagen, bis das Gitter dicht ist.
  \item Decken Sie mit Grasbüscheln von unten nach oben, jede Lage überlappt die darunterliegende um 5 cm.
  \item Füllen Sie Böden mit 10 cm trockenem Laub oder Gras (Kapitel 6.1).
  \item Verschließen Sie die Öffnung mit einem geflochtenen Grasvorhang, im Notfall mit einer Astwand.
\end{enumerate}

\begin{tabular}{p{4.0cm}p{5.0cm}p{5.0cm}}
\toprule
Wetterlage & Sofortmaßnahme & Fehler, den Sie vermeiden \\
\midrule
Trocken, windstill & Behelftyp Lehmgroßhütte & Überbau; Zeit fehlt dann für Feuer \\
Regen erwartet & Plane zuerst, Astwerk danach & Grasdecke auf nasse Astlagen \\
Sturm erwartet & Halbhöhe bauen, Windbruch vor die Tür & Hohe Firstlinie \\
Dauerregen läuft & Behelf aufgeben, Höhlen oder Kapitel 4 suchen & Nasse Graslage nachlegen \\
\bottomrule
\end{tabular}
\end{konzept}

\subsection{Übersicht Behelftypen}

\begin{baustein}
\merk{Behelf schützt vor Wind und Regen, nicht vor Kälte.} Kälte stoppt nur die Isolierung, Kapitel 6. \\
\merk{Baue klein, schlafe warm, arbeite am Morgen.}
\end{baustein}

\section{Kapitel-Checkliste: Die erste Nacht}

\begin{checkliste}
\item Standort hat die vier Kriterien erfüllt und ist protokolliert (Vorlage A.4).
\item Materialliste ist vollständig beschafft, bevor der Aufbau beginnt.
\item Aufbau-Schritte in der nummerierten Reihenfolge ausgeführt.
\item CO-Warnung gelesen; niemals Flamme im geschlossenen Behelf ohne Öffnung.
\item Rückbau in unter 24 Stunden möglich; Plan eingetragen (Vorlage A.5).
\end{checkliste}
