\chapter{Hüttenbau I: Bauplan und Gerüst}
% =====================================================================

\section{Konzept 4.1: Der Bauplan auf einem Blatt}

\begin{konzept}{4.1 – Der Bauplan auf einem Blatt}
\textbf{Definition.} Der Bauplan ist eine Maßskizze der Hütte mit vier Angaben: Grundfläche, Firsthöhe, Türöffnung, Lagerzahl. Er passt auf ein Blatt (Vorlage A.6) und wird vor dem ersten Schlag geschrieben.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Probeplan für drei Behelftypen aus Kapitel 3 gerechnet.
  \item Nachmessen am fertigen Bau; Abweichung über 10 Prozent: Plan und Ausführung vergleichen.
  \item Prüfung gegen die Aufwandsbegrenzung, Kapitel 1.1, Regel 5.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: jede Maßangabe wird in den Kapiteln 5 und 6 verwendet.
  \item Praxistauglichkeit: kein Rechenwerk, nur Addieren und Halbieren.
  \item Ehrlichkeit: ein Plan ersetzt kein Können; die ersten Bauern sind langsam, Faustwert: doppelte Zeit.
\end{enumerate}

\textbf{Grenzen.} Der Plan gilt für ebene Böden. Bei Hanglage ersten Schritt 5.2 (Terrassierung) vorziehen.

\textbf{Grundmaße für 1 bis 4 Personen.}

\begin{tabular}{p{3.0cm}p{3.2cm}p{3.2cm}p{3.4cm}}
\toprule
Personen & Grundfläche & Firsthöhe & Liegefläche je Person \\
\midrule
1 & 180 mal 120 cm & 120 cm & 180 mal 60 cm \\
2 & 240 mal 160 cm & 140 cm & 180 mal 70 cm \\
3 & 300 mal 200 cm & 160 cm & 180 mal 60 cm \\
4 & 360 mal 240 cm & 180 cm & 180 mal 60 cm \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Plan in 15 Minuten.}
\begin{enumerate}
  \item Zeichnen Sie die Grundfläche maßstäblich (1 Kasten = 10 cm).
  \item Zeichnen Sie den First als Linie, schreiben Sie die Firsthöhe daneben.
  \item Markieren Sie die Tür an Lee (Konzept 2.2).
  \item Zeichnen Sie jede Liegefläche als Rechteck; lassen Sie 40 cm Gang frei.
  \item Schreiben Sie die Materialliste an den Rand (Vorlage A.7).
  \item Legen Sie das Blatt sichtbar auf; bei jeder Abweichung eintragen, nicht rekonstruieren.
\end{enumerate}
\end{konzept}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-4-1}
\caption{Abb. 4.1 – Grundriss und Aufriss einer Zwei-Personen-Hütte mit Maßangaben}
\end{figure}

\section{Konzept 4.2: Gerüst: Stützen, Riegel, Zapfenlager}

\begin{konzept}{4.2 – Gerüst: Stützen, Riegel, Zapfenlager}
\textbf{Definition.} Das Gerüst ist die tragende Holzstruktur: vier Eckstützen, zwei Firststützen, Riegel als Querverbände. Verbindungen ohne Nägel: Zapfenlager (A in Ast), Schnürbund, Scherengitter.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Belastungsprobe: fertiges Gerüst, 60 kg Sand oder Equivalent in der Mitte des Firsts, 5 Minuten.
  \item Sturmprobe im Vorfeld der Ausführung nur am stehenden, leeren Gerüst: Fahnenprobe 2.2, dann Abschätzung.
  \item Rückbau-Zeit gestoppt: jede Verbindung lösbar ohne Sägeschaden.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: drei Verbindungstypen decken alle Knoten des Bandes.
  \item Praxistauglichkeit: ohne Nägel, ohne Bohrer.
  \item Ehrlichkeit: nagellose Verbindungen brauchen Nacharbeit; alle 14 Tage prüfen.
\end{enumerate}

\textbf{Grenzen.} Überschreiten Sie 200 cm Firsthöhe nicht ohne Zusatzstützen in Feldmitte. Grünholz scheuert Schnüre; bei Feuchtwetter alle 7 Tage nachziehen.

\textbf{Verbindungstabelle (ohne Nägel).}

\begin{tabular}{p{3.4cm}p{4.4cm}p{6.0cm}}
\toprule
Verbindung & Einsatz & Ausführung, Faustwerte \\
\midrule
Zapfenlager & Stütze auf Riegel & A-Kerbe 2 cm tief, 8 cm lang; Stütze muss 20 cm Restquerschnitt behalten \\
Schnürbund & Stütze mit Riegel & 6 Wicklungen, Trockenmaterial, Enden verkeilt \\
Scherengitter & First gegen Wind & Zwei gekreuzte Stangen, unten eingegraben 20 cm, oben gebunden \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Gerüst stehen (4 Stunden, zwei Personen).}
\begin{enumerate}
  \item Eckpunkte abstecken mit Schnurviereck; Diagonalen vergleichen, Abweichung unter 5 cm.
  \item Vier Eckstützen aufstellen, Stärke Faustwert: mindestens Handgelenkdurchmesser oben, 8 cm breite Basisfläche.
  \item Erdstützen 30 cm eingraben, Steinplatte unter die Basis gegen Einsinken.
  \item Riegel auf Brusthöhe einlegen, Schnürbund um jede Ecke, 6 Wicklungen.
  \item Zwei Firststützen innen, gerundete Kopplung mit dem Firstriegel.
  \item Diagonalverbände: je Wandseite ein Scherengitter in einer Ecke.
  \item Belastungsprobe nach der Tabelle oben; Beulen oder Knarren: Verbindung nachziehen.
  \item Alle 14 Tage: Bundprobe, jede Verbindung mit der Hand bewegen; Spiel über 2 mm heißt nachziehen.
\end{enumerate}
\end{konzept}

\begin{warnbox}
\textbf{Einsturzgefahr beim Gerüstbau.} Ein unvollständiges Gerüst trägt nicht. Steigen Sie niemals auf Riegel oder Firststützen, bevor alle Verbindungen gesetzt und belastungsgeprüft sind. Stürze aus über 150 cm auf Kopf oder Wirbelsäule sind ohne ärztliche Hilfe im Ernstfall oft dauerhaft. Regel: von oben arbeiten Sie nur mit Dreipunkt-Halt (zwei Hände und ein Fuß oder zwei Füße und eine Hand) und nie allein. Bei Wind über Fahnenprobe-Stärke 3 (Band flattert waagerecht): Gerüstbau sofort einstellen.
\end{warnbox}

\section{Konzept 4.3: Werkzeuge und Ersatzwerkzeuge}

\begin{konzept}{4.3 – Werkzeuge und Ersatzwerkzeuge}
\textbf{Definition.} Der Band braucht fünf Kernwerkzeuge: Säge, Beil, Schnurmesser, Brechstange, Steckenmesser (Stockmesser). Für jedes Kernwerkzeug gibt es zwei Ersatzwege, falls es fehlt oder bricht.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Bau eines Gerüstes einmal nur mit Ersatzwegen, Zeitstopp (Übung C.7).
  \item Schnittsicherheit: jede Anleitung nur mit Kernwerkzeug oder Ersatzweg lösbar.
  \item Prüfung der Wartungsregeln gegen Band 3 (Schärfen am Wetzstein).
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: keine Anleitung der Kapitel 3 bis 9 verlangt Spezialwerkzeug.
  \item Praxistauglichkeit: alle Ersatzwege mit Fundmaterial erreichbar.
  \item Ehrlichkeit: Ersatzwege kosten das Zwei- bis Dreifache an Zeit, Faustwert.
\end{enumerate}

\textbf{Grenzen.} Ohne jede Schneidekante ist kein Kapitel-4-Bau möglich;Priorität liegt dann auf Kapitel-3-Behelfen.

\begin{tabular}{p{2.8cm}p{4.4cm}p{7.0cm}}
\toprule
Kernwerkzeug & Ersatzweg eins & Ersatzweg zwei \\
\midrule
Säge & Metallsägeblatt aus Abbruch & Reibungsschnitt mit Stein­kante (Faustwert) \\
Beil & Hammer und Keil, Spaltaxt aus Abbruch & Feuerring-Methode nach Band 3 (Baumfällring) \\
Schnurmesser & scharfkantige Blechlasche & geschlagene Glasscherbe in Lederwicklung \\
Brechstange & Hartholzhebel, Eiche 5 cm stark & Hebelarm über Steinauflage \\
Steckenmesser & harter Knochen, gehärtet & gehärtetes Blech, geschliffen am Beton \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Werkzeug-Tagescheck (5 Minuten, jeden Morgen).}
\begin{enumerate}
  \item Schneide auf Licht prüfen; ausgebrochene Stelle 5 Minuten am Wetzstein nachziehen.
  \item Griff wackeln? Ja: Keil nachschlagen oder Wickelband neu.
  \item Schnittgut des Vortags trocknen; nasses Werkzeug rostet.
  \item Ersatzweg des am meisten benutzten Werkzeugs bereithalten, nicht suchen müssen.
\end{enumerate}
\end{konzept}

\section{Kapitel-Checkliste: Bauplan und Gerüst}

\begin{checkliste}
\item Bauplan auf einem Blatt mit vier Angaben liegt sichtbar am Bau.
\item Grundfläche und Firsthöhe stimmen mit der Personenzahl-Tabelle überein.
\item Alle Verbindungen sind zapfen-, bund- oder gitterbasiert; keine Nägel nötig.
\item Belastungsprobe mit 60 kg über 5 Minuten bestanden.
\item Warnung Gerüstbau gelesen; Klettern nur mit Dreipunkt-Halt.
\item Fünf Kernwerkzeuge oder Ersatzwege vorhanden; Tagescheck läuft.
\end{checkliste}

