\chapter{Hüttenbau II: Dach, Wand und Boden}
% =====================================================================

\section{Konzept 5.1: Das Dach: Neigung, Lagen, First}

\begin{konzept}{5.1 – Das Dach: Neigung, Lagen, First}
\textbf{Definition.} Das Dach besteht aus drei Lagen: Sparrenwerk (tragend), Deckwerk (Regen) und Firstabdichtung (Wassereintritt von oben). Die Mindestneigung für pflanzliche Deckung liegt bei 45 Grad, Faustwert.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Regenprobe: 20 Liter Wasser gleichmäßig über 2 Minuten auf 1 m\textsuperscript{2} Deckung.
  \item Neigungsmessung mit Schnur undlot: Winkel an allen vier Sparrenpaaren.
  \item Windprobe nach Fahnen-Regel 2.2, Deckung bleibt in Stärke-3-Wind vollständig aufliegend.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: 45-Grad-Regel gilt für Stroh, Gras, Schilf; Planen dürfen flacher (30 Grad).
  \item Praxistauglichkeit: Deckung ohne Klammern, nur mit Lagen und Bindern.
  \item Ehrlichkeit: keine Deckung hält Sturmböen über Stärke 6, Faustwert; dann Zelt sichern oder aufgeben.
\end{enumerate}

\textbf{Grenzen.} Schneedruck: ab 30 cm Schnee je 1 m\textsuperscript{2} Last abkehren, Faustwert nach Gewichtsschätzung; Deckung nicht begehen.

\textbf{Deckmaterial-Tabelle.}

\begin{tabular}{p{3.0cm}p{3.0cm}p{3.6cm}p{3.6cm}}
\toprule
Material & Mindestneigung & Lagenzahl, überlappend & Haltbarkeit, Faustwert \\
\midrule
Gras, Heu & 45 Grad & 3 Lagen, je 5 cm Überstand & 1 bis 2 Saisons \\
Schilf & 45 Grad & 2 Lagen, gebunden & 2 bis 3 Saisons \\
Stroh & 45 Grad & 3 Lagen & 1 bis 2 Saisons \\
Plane & 30 Grad & 1 Lage, gespannt & Monate, UV-abhängig \\
Grassoden (Wurzel unten) & 30 Grad & 1 Lage & 1 bis 2 Saisons \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Deckung (5 Stunden, zwei Personen, Dach 240 mal 160 cm).}
\begin{enumerate}
  \item Sparren mit 40 cm Abstand nageln (oder binden, 4.2) auf den Firstriegel.
  \item Grundlatte an der Traufe befestigen; hier beginnt die unterste Decklage.
  \item Erste Decklage von unten nach oben auflegen, Stängel in Fallrichtung, 5 cm Überstand über die Traufe.
  \item Decklage mit Schnurbund am Sparren fixieren, je 30 cm ein Bund.
  \item Zweite Lage überlappend um die halbe Stängellänge versetzen.
  \item Am First die Lagen kreuzweise umschlagen; Firstdeckel aus gebundenen Stängelbündeln.
  \item Regenprobe von innen: bei Tageslicht keine Lichtpunkte sichtbar.
  \item Nach dem ersten Regen von innen prüfen; Undichtigkeiten mit zusätzlichem Stängelbündel nachstopfen.
\end{enumerate}
\end{konzept}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-5-1}
\caption{Abb. 5.1 – Dachaufbau: Sparren, Lagen, First in der Seitenansicht}
\end{figure}

\section{Konzept 5.2: Wand: Flechtwerk, Soden, Lehmflick}

\begin{konzept}{5.2 – Wand: Flechtwerk, Soden, Lehmflick}
\textbf{Definition.} Drei Wandtypen: Flechtwerk (luftig, schnell), Grassoden (schwer, winddicht), Lehmflick auf Flechtwerk (wärmer, arbeitsaufwendig). Auswahl nach Temperatur und Zeit.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Winddichtigkeitsprobe: Rauchfahne außen, Wind stärke 2, innen keine Zugluft an der Hand.
  \item Regenprobe über 2 Stunden Niesel; Innenfläche trocken.
  \item Rückbau der Sondenwand: Unterfläche 4 Wochen unberührt gelassen, danach Zustandsprüfung.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: drei Typen decken Stadt (Flechtwerk mit Karton), Land (Soden, Lehm).
  \item Praxistauglichkeit: Material in Gehweite.
  \item Ehrlichkeit: Lehm reißt beim Trocknen; Nacharbeit mit feuchtem Lehm­schlicker nötig.
\end{enumerate}

\textbf{Grenzen.} Sodenwände wiegen viel; nur auf tragfähigem, ebenem Boden (5.3). Lehmwand braucht Frostfreiheit zum Trocknen; bei Frost nicht anlegen.

\begin{tabular}{p{2.8cm}p{3.8cm}p{3.8cm}p{3.8cm}}
\toprule
Typ & Zeitbedarf & Winddicht & Stadt-/Land-Nutzung \\
\midrule
Flechtwerk & 3 Stunden je Wandfläche 2 m\textsuperscript{2} & mäßig & Stadt: Karton statt Stängel \\
Grassoden & 5 Stunden je m\textsuperscript{2} & hoch & Land: Wiesenrand \\
Lehmflick & 6 Stunden je m\textsuperscript{2} plus Trockenzeit 3 Tage & hoch & beide, wo Lehm erreichbar \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Flechtwand (3 Stunden).}
\begin{enumerate}
  \item Pfosten im Abstand 40 cm setzen, Erdtiefe 30 cm.
  \item Weide, Hasel oder Stängel horizontal einflechten, dicht an dicht.
  \item Jede zweite Reihe mit der Hand andrücken; keine Lücken über 1 cm.
  \item Oberste Reihe verspinnen und kappen.
  \item Windprobe; Lücken mit Karton oder dichterem Flecht nacharbeiten.
\end{enumerate}

\textbf{Anleitung: Lehmflick auf Flechtwerk (6 Stunden plus 3 Tage Trocknung).}
\begin{enumerate}
  \item Lehm ansetzen: 3 Teile Lehm, 1 Teil Sand, Wasser bis zähflüssig (Faustprobe: Kugel bleibt formstabil).
  \item Schnittgut (Stroh 3 cm) unterrühren, Faustwert: 1 Handvoll je Eimer.
  \item Erste Schicht fingerdick von unten auftragen; nie von oben beginnen.
  \item 24 Stunden antrocknen lassen; Risse mit feuchter zweiter Schicht schließen.
  \item Dritte Schicht nur bei Bedarf, Raumauftrag fingerdick.
\end{enumerate}
\end{konzept}

\section{Konzept 5.3: Boden: Terrassierung, Lagerrost, Drainage}

\begin{konzept}{5.3 – Boden: Terrassierung, Lagerrost, Drainage}
\textbf{Definition.} Der Hüttenboden hat drei Aufgaben: Last verteilen, Feuchtigkeit vom Fuß fernhalten, Ebene schaffen. Bau: Terrassierung am Hang, Lagerrost aus Rundhölzern, Drainagering außen.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Standfestigkeitsprobe: volle Liegefläche belasten, 10 Minuten, kein Hohlknarren.
  \item Feuchteprobe nach Regen: Bodenfläche unter dem Rost trocken.
  \item Hangprobe bei 10 Grad Neigung: Terrassenkante bleibt ohne Rutschen.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Rosthöhe 10 cm entspricht Konzept 2.1, Leitungswert Boden.
  \item Praxistauglichkeit: nur Rundholz und Schnur nötig.
  \item Ehrlichkeit: Drainagering versandet mit der Zeit; nach 3 Monaten nachziehen.
\end{enumerate}

\textbf{Grenzen.} Bei Grundwasser unter 40 cm unter Oberfläche keinen Rost bauen, Standort wechseln (3.1).

\textbf{Anleitung: Lagerrost (3 Stunden).}
\begin{enumerate}
  \item Fläche einmessen; Diagonalen abgleichen.
  \item Acht Querlager aus Rundholz (7 cm stark) im Abstand 60 cm legen.
  \item Längsbretter oder halbe Stangen auf die Querlager, Abstand 2 cm für Luft.
  \item Querlager gegen Verrutschen mit Erdnägeln (Y-Gabeln, 20 cm tief) sichern.
  \item Lattenband oberste Ebene: keine Schraube, Schnürbund je Kreuzung.
  \item Belastungsprobe über alle Felder, 10 Minuten, Geräuschprobe mit dem Ohr am Boden.
\end{enumerate}

\textbf{Anleitung: Drainagering (2 Stunden).}
\begin{enumerate}
  \item Rings um die Hütte eine 20 cm tiefe, 20 cm breite Graben ziehen, 50 cm Abstand von der Wand.
  \item Grabensohle mit 2 Prozent Gefälle zur Abflusssicht führen (Schnurwaage, Vorlage A.8).
  \item Graben mit Schotter oder grobem Schnittgut füllen, obere 5 cm offen lassen.
  \item Abflussanschluss in vorhandene Senke; niemals in Brunnen oder Nachbargrund.
\end{enumerate}
\end{konzept}

\begin{baustein}
\merk{Dach zuerst, Wand danach, Boden zuletzt? Nein: Boden zuerst.} Ein trockener Rost verhindert Kapillarwasser vor jeder Wanddichtung. \\
\merk{Dachneigung unter 45 Grad bei Stroh heißt nage Nacht.}
\end{baustein}

\section{Kapitel-Checkliste: Dach, Wand, Boden}

\begin{checkliste}
\item Dachneigung gemessen, mindestens 45 Grad bei pflanzlicher Deckung.
\item Decklagen überlappen um 5 cm; Regenprobe von innen ohne Lichtpunkte.
\item Wandtyp gewählt und Windprobe bestanden.
\item Lehmflick nach 24 Stunden auf Risse geprüft, zweite Schicht aufgetragen.
\item Lagerrost liegt 10 cm über Boden, Belastungsprobe bestanden.
\item Drainagering mit Gefälle und Abfluss in Senke ausgeführt.
\end{checkliste}
