\chapter{Isolierung und Schlafplätze: die Nacht warm halten}
% =====================================================================

\section{Konzept 6.1: Isolierschichten: trocken, dick, luftig}

\begin{konzept}{6.1 – Isolierschichten: trocken, dick, luftig}
\textbf{Definition.} Isolierung ist eingeschlossene Luft in trockenem Material. Drei Regeln: Material trocken, Schicht dick, Struktur luftig. Faustwert für den Schlafplatz: 20 cm trockenes Füllmaterial unter dem Körper, 10 cm über dem Boden als Luftsperrschicht.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Feuchtemessung ohne Gerät: Füllmaterial eine Nacht in geschlossenem Behälter – beschlagene Wand heißt zu feucht.
  \item Kälteprobe: Faustprobe 2.1 über 5 Minuten auf der fertigen Schlafstelle.
  \item Wiederholungsprobe nach 7 Tagen Nutzung; Füllmaterial ohne Setzstellen unter 10 cm.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: jeder Stoff der Tabelle wirkt über Lufteinschluss, nicht über Masse.
  \item Praxistauglichkeit: Materialien ohne Verarbeitung nutzbar.
  \item Ehrlichkeit: jede Isolierung versagt, wenn sie nass wird; Trocknen kostet Tageszeit.
\end{enumerate}

\textbf{Grenzen.} Füllmaterial aus dem Freien bringt Insekten ein; Ausschütteln und Sonnenexposition von 2 Stunden vor dem Einbau, Faustwert.

\begin{tabular}{p{3.4cm}p{3.2cm}p{3.4cm}p{3.6cm}}
\toprule
Material & Fülldicke, Faustwert & Nachteil & Austausch nach \\
\midrule
Trockenes Laub & 20 cm & Setzt um die Hälfte & 7 Tage \\
Gras, Heu & 20 cm & Feuchtigkeitsspeicher & 14 Tage \\
Nadelzweige & 15 cm & Harz an Textil & 14 Tage \\
Stroh & 15 cm & Nagetiere & 14 Tage \\
Trockenmoos & 10 cm & schwer zu erneuern & einmalig \\
Kartonschnipsel (Stadt) & 15 cm & verliert Luft bei Nässe & 7 Tage \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Schlafplatz aufbauen (90 Minuten).}
\begin{enumerate}
  \item Fläche 180 mal 80 cm abstecken, an der Innenwand, Tür in Sichtweite.
  \item Untere Schicht: dichtes Astgitter oder Kartonlage, 10 cm hoch – Luftpolster gegen Boden.
  \item Mittlere Schicht: Füllmaterial trocken einfüllen, angepresst und nachgefüllt bis 20 cm über dem Gitter.
  \item Obere Schicht: Planenstück oder dichtes Grasgeflecht als Feuchtigkeitsstopp.
  \item Decklage: Wolldecke, Filz oder Grasgewebe; Körperseite bleibt atmungsaktiv.
  \item Faustprobe auf allen vier Ecken; kalt heißt nachfüllen.
  \item Nach jeder Nacht: Füllmaterial aufschütteln; Setzstellen sofort auffüllen.
  \item Alle 7 Tage: Füllmaterial komplett austauschen oder 4 Stunden sonnen und wenden.
\end{enumerate}
\end{konzept}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-6-1}
\caption{Abb. 6.1 – Schlafplatz im Schichtenmodell: Gitter, Füllung, Stopp, Decke}
\end{figure}

\begin{warnbox}
\textbf{Unterkühlung im Schlaf.} Wer im Schlaf auskühlt, wacht nicht rechtzeitig auf: Der Körper drosselt bei Kälte die Weckreaktion, und Betroffene werden passiv statt aktiv. Das ist die gefährlichste Phase einer Nacht – schwer und irreversibel, wenn sie durchschlafen. Drei Regeln: nie mit nasser Kleidung schlafen, nie auf nur einer dünnen Schicht ruhen, und den Kopf mit isolierter Mütze bedecken. Zittert eine Person im Schlaf, oder ist sie morgens verwirrt und sagt, es gehe ihr gut: Füllmaterial verdoppeln, Person mit trockener Decke umhüllen, warmes Getränk nach Band 1, und nicht allein lassen.
\end{warnbox}

\section{Konzept 6.2: Der Schlafsack und seine Behelfe}

\begin{konzept}{6.2 – Der Schlafsack und seine Behelfe}
\textbf{Definition.} Der Schlafsack ist eine Hülle, die Körperwärme staut. Behelfe ersetzen ihn: Wolldeckenschlafsack, Grasnatte, Zeitungs-Karton-Hülle. Jede Hülle wirkt nur mit trockener Basisschicht (Kapitel 8.1).

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Temperaturprobe: Behelfshülle bei 5 Grad, Dauer 6 Stunden, Aufwachtemperatur mit Handgefühl protokolliert.
  \item Feuchteprobe: Morgentest auf Innenfeuchte; beschlagene Hülle trocknen, bevor sie wiederverwendet wird.
  \item Dauerprobe: fünf Nächte hintereinander gleiche Hülle, Zustand protokolliert (Übung C.8).
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Behelfe aus Stadt- und Landmaterial herstellbar.
  \item Praxistauglichkeit: ohne Nähmaschine, nur Knüpf- und Wickeltechnik (Kapitel 7.3).
  \item Ehrlichkeit: Behelfe erreichen nie Komfortwerte von Federschlafsäcken; sie halten überlebensfähig, nicht gemütlich.
\end{enumerate}

\textbf{Grenzen.} Bei dauerhaft unter 0 Grad reicht keine Behelfshülle allein; zusätzliche Füllschicht und beheizter Vorraum (Band 3) nötig.

\begin{tabular}{p{3.6cm}p{3.4cm}p{4.0cm}p{2.6cm}}
\toprule
Behelf & Herstellzeit & Material & Untergrenze, Faustwert \\
\midrule
Wolldeckenschlafsack & 1 Stunde & 2 Decken, 8 Sicherheitsnadeln & 5 Grad \\
Filz-Hülle & 2 Stunden & 2 m Filz, Bindfaden & 0 Grad \\
Karton-Zeitung-Rolle & 30 Minuten & Karton, 10 Zeitungen & 5 Grad, trocken nur \\
Grasnatte mit Hülle & 3 Stunden & Grasseil, Planenstück & 5 Grad \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Wolldeckenschlafsack (1 Stunde).}
\begin{enumerate}
  \item Beide Decken übereinanderlegen, glatt streichen.
  \item Längs falten; untere Kante 30 cm offen lassen als Fußraum.
  \item Längsnaht mit Kombination: Sicherheitsnadeln alle 15 cm außen, innen gefaltet.
  \item Fußende mit 4 Nadeln schließen, Kopfende offen.
  \item Einsteigen nur in trockener Kleidung; feuchte Socken draußen lassen.
  \item Morgens 30 Minuten lüften, Decken offen, vor direkter Sonne.
\end{enumerate}
\end{konzept}

\section{Konzept 6.3: Kältebrücken finden und schließen}

\begin{konzept}{6.3 – Kältebrücken finden und schließen}
\textbf{Definition.} Eine Kältebrücke ist eine Stelle, an der Wärme schneller entweicht als im Umfeld: Bodenkontakt, Nahtstelle, Türspalt, feuchte Stelle. Finden mit der Faustprobe 2.1, schließen mit Nachschichten.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Faustprobe an 8 festen Punkten jeder Unterkunft, Woche 1 bis 4.
  \item Dampfprobe: Atem in den Raum, Kondensat zeigt Undichtigkeiten.
  \item Rauchprobe außen bei Wind stärke 2; Zugluftwege innen mit der Hand寻找, besser: mit angefeuchtetem Handrücken.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: jede Maßnahme folgt direkt aus Konzept 2.1.
  \item Praxistauglichkeit: alle Prüfungen ohne Werkzeug.
  \item Ehrlichkeit: jede geschlossene Brücke senkt Luftaustausch; Lüften morgens 15 Minuten bleibt Pflicht.
\end{enumerate}

\textbf{Grenzen.} Totalabdichtung ohne Lüftungsplan erzeugt Kondenswasser; Feuchtigkeit schlägt sich am kältesten Punkt nieder.

\textbf{Kältebrücken-Tabelle: Fall und Maßnahme.}

\begin{tabular}{p{4.4cm}p{5.0cm}p{5.4cm}}
\toprule
Befund & Ursache, Faustwert & Maßnahme \\
\midrule
Boden fühlt kalt an der Liegefläche & Füllung unter 10 cm, gesetzt & Füllung austauschen, Gitter erhöhen \\
Wand zieht an der Schulter & Flechtwerk mit Lücken über 1 cm & Kartoninnenschicht oder Lehmflick \\
Türspalt fühlbar am Fuß & Tür schließt nicht dicht & Grasvorhang, zweite Türmatte außen \\
Nasse Decke am Morgen & Kondensat, zu dicht abgedichtet & 15 Minuten lüften, Stopp-Schicht prüfen \\
Frost an der Innenwand & Deckung dünn am First & Firstbündel nachlegen, Zwischenschicht \\
\bottomrule
\end{tabular}
\end{konzept}

\begin{baustein}
\merk{Trocken ist wärmer als dick: nasse Isolierung ist keine.} \\
\merk{Faustprobe jede Woche, vier Ecken, eine Minute je Ecke.}
\end{baustein}

\section{Kapitel-Checkliste: Isolierung und Schlafplätze}

\begin{checkliste}
\item Schlafplatz hat drei Schichten: 10 cm Luftgitter, 20 cm trockene Füllung, Feuchtigkeitsstopp.
\item Füllmaterial ist getestet: trocken, sonnenexponiert, insektenfrei (Faustwert).
\item Behelfsschlafsack hergestellt und fünf Nächte geprüft.
\item Acht Punkte-Faustprobe wöchentlich ausgeführt und protokolliert.
\item Kältebrücken-Tabelle angewendet; offene Brücken null.
\item Morgendliches Lüften, 15 Minuten, steht im Tagesplan.
\item Warnung Unterkühlung gelesen; Regeln bei Zittern bekannt.
\end{checkliste}

