\chapter{Textilkunde: Faser, Pflege, Nadel und Faden}
% =====================================================================

\section{Konzept 7.1: Fasern kennen und prüfen}

\begin{konzept}{7.1 – Fasern kennen und prüfen}
\textbf{Definition.} Vier Faserfamilien bestimmen alles Textile des Bandes: Wolle (warm, feuchteresistent), Baumwolle (kühl, kältegefährlich nass), Kunstfaser (leicht, schnelltrocknend, hitzeempfindlich), Pflanzenbast (Brennnessel, Hanf, für Schnur und Gewebe).

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Brennprobe an Faserbüscheln: Geruch, Asche, Verhalten (Übung C.9, draußen, Feuer nach Band 3).
  \item Nassfestigkeitsprobe: Faser nass ziehen, Faustwert nach Tabelle.
  \item Trageprobe: 24 Stunden gleiche Faser am Körper, Hautreaktion protokollieren.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: jede Faserfamilie hat eine feste Rolle in Kapitel 8.
  \item Praxistauglichkeit: Brennprobe überall durchführbar.
  \item Ehrlichkeit: Mischgewebe sind schwer einzuordnen; wenn unsicher, wie Baumwolle behandeln.
\end{enumerate}

\textbf{Grenzen.} Faserkunde ersetzt keine Lagerhaltung: Neue Kleidung entsteht nur mit großem Zeitaufwand (Konzept 7.3, Grenzen dort).

\begin{tabular}{p{2.6cm}p{3.4cm}p{3.4cm}p{4.4cm}}
\toprule
Faser & nass & Brennprobe, Geruch & Rolle im Satz \\
\midrule
Wolle & bleibt warm & Horngeruch, krümelige Asche & Wärmelagen, Socken \\
Baumwolle & kühlt stark & Papiergeruch, weiche Asche & Sommerlagen, Wickel \\
Kunstfaser & trocknet schnell & schmilzt, Perlen, süßlich & Außenlage, Wind- und Regenschutz \\
Bast (Nessel, Hanf) & wird fester & wie Papier, hartes Reststück & Schnur, Gewebe, Netze \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Brennprobe (5 Minuten, draußen).}
\begin{enumerate}
  \item Faserbüschel von 10 Fäden abzwicken, an einem Bindfaden aufhängen.
  \item Flamme nach Band 3, Faser in die Flamme halten, sofort zurückziehen.
  \item Geruch einatmen nicht; über die Hand fächeln, Geruch nur im Vorbeiziehen prüfen.
  \item Asche betrachten: krümelig, weich oder geschmolzene Perlen.
  \item Ergebnis in die Fasertabelle eintragen; Probe nur draußen, Wind abgewandt.
\end{enumerate}
\end{konzept}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-7-1}
\caption{Abb. 7.1 – Brennprobe: Zuordnung der vier Faserfamilien über Geruch und Asche}
\end{figure}

\section{Konzept 7.2: Pflege ohne Waschmaschine}

\begin{konzept}{7.2 – Pflege ohne Waschmaschine}
\textbf{Definition.} Textilpflege im Ernstfall heißt: Trocknen, Ausbürsten, Fleckentfernung mit kaltem Wasser, Ausklopfen, Lüften. Waschen ist die Ausnahme; jedes Waschen verkürzt die Lebensdauer der Wärmeleistung.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Drei Wolldecken über 30 Tage nur mit Pflegeplan (Übung C.10) behandelt; Wärmeleistung mit Faustprobe verglichen.
  \item Fleckentfernungsprobe an drei Stoffarten mit kaltem Wasser und Bürste.
  \item Vergleich: gewaschene gegen nur gelüftete Decke in derselben Periode.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Pflegeplan folgt dem Faustwert „Wärmeleistung = eingeschlossene Luft“.
  \item Praxistauglichkeit: kaltes Wasser, Bürste, Sonne genügen.
  \item Ehrlichkeit: Wolle verfilzt bei falscher Behandlung; nach einmaligem Feltzer bleibt die Leistung dauerhaft halbiert.
\end{enumerate}

\textbf{Grenzen.} Bei Parasitenbefall (Läuse, Flöhe) gilt Ausnahme: Wäschegut über Dampf oder Hitze behandeln, Band 3 Grubenglut, 60 Grad für 10 Minuten, Faustwert.

\begin{tabular}{p{3.6cm}p{4.4cm}p{4.4cm}}
\toprule
Zustand & Pflegemaßnahme & Verboten \\
\midrule
Feucht, aber sauber & offen lüften, 2 Stunden, Wind & an Feuer oder Herd \\
Trocken, Staub & Ausklopfen an Stein, Bürste ab & Waschen \\
Fleck, frisch & kaltes Wasser, Ausreiben, Schatten trocknen & heißes Wasser (Eiweiß) \\
Wolldecke verfilzt & Bürsten in eine Richtung, sanft & Dehnen, Reiben im Kreis \\
Kunstfaser stinkt & Waschen, kalt, Seifenlösung & heiß trocknen (schmilzt) \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Wäschetag ohne Maschine (2 Stunden, alle 14 Tage).}
\begin{enumerate}
  \item Tragbare Textilien sortieren: Wolle separat, Kunstfaser separat, Baumwolle separat.
  \item Wolle: 10 Minuten in kaltem Wasser, kein Reiben, sanft ausdrücken, flach trocknen.
  \item Kunstfaser: 20 Minuten in Seifenlösung, spülen, wringen erlaubt, im Schatten trocknen.
  \item Baumwolle: kalt waschen, wringen, an der Sonne trocknen.
  \item Alle Nähstellen prüfen; aufreißende Naht sofort heften (7.3).
  \item Trockengut waagerecht lagern, nicht aufgehängt an der Naht.
\end{enumerate}
\end{konzept}

\section{Konzept 7.3: Nadel, Faden und Notnaht}

\begin{konzept}{7.3 – Nadel, Faden und Notnaht}
\textbf{Definition.} Nähen im Band heißt: Heften (Notnaht), Flicken, Schnürnaht (Verbindung zweier Stoffkanten ohne Nahtzugabe). Werkzeug: eine Nadel, ein Faden aus Vorrat oder gesponnene Bastfaser.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Zugprobe an jeder Naht: Faden hält das 5-fache des Stoffgewichts pro Zentimeter Naht, Faustwert.
  \item Trageprobe über 7 Tage: Naht scheuert nicht an der Haut.
  \item Wiederholungsprobe nach 3 Wäschen: Naht hält ohne Aufgehen.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: drei Techniken decken alle Reparaturen der Kapitel 6 bis 9.
  \item Praxistauglichkeit: eine Nadel reicht; Ersatznadel aus gehärtetem Splint.
  \item Ehrlichkeit: Genähtes ist nie wie neu; Flicken verlängern, sie erneuern nicht.
\end{enumerate}

\textbf{Grenzen.} Neue Kleidung aus Rohfaser herstellen dauert Wochen und setzt Spinnkönnen voraus; dieser Band beschränkt sich auf Reparatur und Umbau vorhandener Textilien.

\textbf{Technik-Tabelle.}

\begin{tabular}{p{3.0cm}p{4.0cm}p{5.0cm}}
\toprule
Technik & Einsatz & Ausführung, Faustwerte \\
\midrule
Notnaht (Heften) & frischer Riss & Stichlänge 5 mm, Faden doppelt, Knoten innen \\
Flicken & Loch über 2 cm & Flicken 3 cm größer als Loch, Vorstich am Rand, 3 mm Abstand \\
Schnürnaht & zwei Kanten verbinden & Lochstich alle 10 mm, Spannung gleichmäßig \\
Knopfersatz & Knopf verloren & Aststück oder Knochen, 4 Löcher, Doppelfaden \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Notnaht in 10 Minuten.}
\begin{enumerate}
  \item Riss glattlegen, Stoffkanten bündig.
  \item Faden doppelt, Länge: Risslänge plus 20 cm.
  \item Ernen Knoten innen, Stichfolge: alle 5 mm, senkrecht durch beide Lagen.
  \item Nahtende mit 2 Knoten innen sichern.
  \item Zugprobe: sanft auseinanderziehen; aufgehende Stiche verdichten.
  \item Scheuerstellen innen mit Flickenstück unterlegen.
\end{enumerate}

\textbf{Anleitung: Flicken (20 Minuten).}
\begin{enumerate}
  \item Loch auf 2 cm prüfen; ausgefranste Kanten abschneiden.
  \item Flicken zuschneiden, rundlich, 3 cm Rand ringsum.
  \item Flicken unter das Loch legen, Muster mit Stecknadeln oder Nadeln markieren.
  \item Vorstich rundum, 3 mm Rand, Doppelfaden.
  \item Zugprobe und Trageprobe; Wollflicken in Wollrichtung.
\end{enumerate}
\end{konzept}

\begin{baustein}
\merk{Baumwolle nass ist ein Kältefalle: nie als Schlafwäsche.} \\
\merk{Flicken größer als das Loch, rund nicht eckig.} \\
\merk{Nähgut trocknen: eine nasse Naht reißt beim Zug.}
\end{baustein}

\section{Kapitel-Checkliste: Textilkunde}

\begin{checkliste}
\item Fasertabelle kann ich ohne Buch aufsayen: Wolle, Baumwolle, Kunstfaser, Bast.
\item Brennprobe sicher draußen ausgeführt; Ergebnisse protokolliert.
\item Pflegeplan läuft: 14-Tage-Rhythmus, Wolle separat.
\item Notnaht und Flicken ohne Hilfe ausführbar; Zugprobe bestanden.
\item Nadel, Doppelfaden und Flickstoffe liegen im Nähset (Vorlage A.9).
\end{checkliste}
