\chapter{Kleidung im Ernstfall: Satz, Beschaffung, Grenzen}
% =====================================================================

\section{Konzept 8.1: Der Kleidungs-Satz: drei Lagen System}

\begin{konzept}{8.1 – Der Kleidungs-Satz: Drei-Lagen-System}
\textbf{Definition.} Der Satz ist die Grundausstattung einer Person für den Jahreszyklus: Basisschicht (Hautfern, feuchtigkeitstransportierend), Wärmeschicht (Lufteinschluss), Schutzhülle (Wind und Regen). Ziel: jede Lage einzeln tauglich, zusammen bis Faustwert minus 10 Grad.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Trageprobe über 3 Tage bei wechselndem Wetter; alle Kombinationen protokolliert (Übung C.11).
  \item Nässeprobe: 30 Minuten Nieselregen in voller Schutzhülle; Basisschicht bleibt trocken.
  \item Bewegungsprobe: 60 Minuten Arbeit in voller Montur ohne Schweißstau.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: jede Lage drosselt genau einen Verlustweg aus Konzept 2.1.
  \item Praxistauglichkeit: keine Spezialware; Second-Hand genügt.
  \item Ehrlichkeit: Baumwolle als Basisschicht versagt nass; der Klassiker ist der Anfängerfehler Nummer 1 (Anhang B).
\end{enumerate}

\textbf{Grenzen.} Der Faustwert minus 10 Grad gilt nur bei Bewegung; im Schlaf gilt Kapitel 6. Extreme Kälte unter minus 20 Grad: dieser Band reicht nicht, Gewänder aus Band 5 und Grubenheizung nach Band 3 kombinieren.

\begin{tabular}{p{2.6cm}p{4.0cm}p{4.0cm}p{4.0cm}}
\toprule
Lage & Funktion & beste Faser & Ersatzfaser \\
\midrule
Basisschicht & Schweiß abführen & Merinowolle, Kunstfaser & gerippte Seide, Nessel \\
Wärmeschicht & Luft speichern & Wolle, Fleece & gestapelte Wolldecken, Filz \\
Schutzhülle & Wind und Regen halten & beschichtetes Gewebe, Leder & dichte Baumwolle, geölte Plane \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Satz prüfen und aufbauen (30 Minuten).}
\begin{enumerate}
  \item Leeren Sie Ihr Kleidungsgut auf eine Fläche; sortieren Sie nach den drei Lagen.
  \item Fehlende Lage: aus Anhang A.10 Beschaffungsliste abhaken; Übergang mit Flickwerk.
  \item Prüfen Sie jede Lage auf Scheuerstellen und Nährisse; heften nach Konzept 7.3.
  \item Bestimmen Sie einen Trockenplatz pro Person: nichts bleibt nass über Nacht.
  \item Packen Sie den Satz in der Reihenfolge: Hülle außen, Wärme mittig, Basis innen.
  \item Dokumentieren Sie den Satz auf der Satzkarte (Vorlage A.11).
\end{enumerate}
\end{konzept}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-8-1}
\caption{Abb. 8.1 – Drei-Lagen-System der Kleidung mit Faserwahl je Lage}
\end{figure}

\section{Konzept 8.2: Beschaffung: Stadt und Land, ehrliche Wege}

\begin{konzept}{8.2 – Beschaffung: Stadt und Land, ehrliche Wege}
\textbf{Definition.} Beschaffung heißt: Kleidung vor dem Ernstfall zusammenstellen. Wege: Vorrat, Tausch, Fund (nur herrenlos), Verarbeitung eigener Faser. Der Weg heißt nicht: nehmen, was anderen gehört.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Zielmengen nach Vorlage A.10 über 30 Tage zusammenstellen; Lücken protokollieren.
  \item Tauschregel geprüft: ein Kleidungsstück entspricht einem Tagesvorrat Arbeit, Faustwert.
  \item Fundregel geprüft: nur herrenlos und ungetragen; Besitzmarken beachten.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Wege decken beide Ausgangslagen.
  \item Praxistauglichkeit: ohne Geldsystem lauffähig.
  \item Ehrlichkeit: jede Neuanschaffung aus dem Nichts scheitert; Vorrat vor dem Ernstfall ist der einzige sichere Weg.
\end{enumerate}

\textbf{Grenzen.} Kapitel 1, Gemeingut-Regel, gilt: Getragen-Gut von Toten ist Bestattungsgut, nicht Vorrat.

\begin{tabular}{p{3.0cm}p{5.4cm}p{5.4cm}}
\toprule
Weg & Stadt & Land \\
\midrule
Vorrat & Haushaltsauflösung, Second-Hand, Lagerbestand & Hofbestand, Keller, Truhe \\
Tausch & Markttag, Werk gegen Ware & Ernteanteil, Arbeit gegen Kleidung \\
Fund (herrenlos) & nur ungetragene, verlassene Ware, deutlich markiert & Heuboden, Weidezaun-Fund erst \\
Eigene Faser & Nessel am Bahndamm, Hanfreste & Wolle, Filz, Leder (Band 5 und 6) \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Beschaffungsplan (60 Minuten).}
\begin{enumerate}
  \item Zählen Sie den Bestand je Lage und Person.
  \item Tragen Sie Fehlendes in Vorlage A.10 ein, mit Dringlichkeit: Hülle vor Wärme vor Basis.
  \item Ordnen Sie jedem Fehlposten einen Weg zu: Vorrat, Tausch, Fund, Faser.
  \item Legen Sie ein Tauschangebot fest: Ihre Arbeitszeit, Ihre Ware.
  \item Wiederholen Sie den Plan alle 3 Monate; Verbrauch protokollieren.
\end{enumerate}
\end{konzept}

\section{Konzept 8.3: Grenzen des Systems Kleidung}

\begin{konzept}{8.3 – Grenzen des Systems Kleidung}
\textbf{Definition.} Kleidung hat drei harte Grenzen: Nässe, Abrieb, Zeit. Keine Lage arbeitet nass, keine Naht hält Abrieb über Monate, kein Vorrat reicht über Jahre ohne Nachschub.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Abriebprobe: bekannte Scheuerstellen nach 30 Tagen Tragezeit messen.
  \item Nässe-Verhalten der vollen Montur im Feldversuch (Übung C.12).
  \item Bestandskontrolle: Satzkarten aller Beteiligten nach 3 Monaten vergleichen.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Grenzen folgen aus Konzept 7.1 und 2.1.
  \item Praxistauglichkeit: Prüfungen ohne Werkzeug.
  \item Ehrlichkeit: ein Notkleidersatz ist kein Ersatz für Reparaturarbeit; er verlagert das Problem.
\end{enumerate}

\textbf{Grenzen der Grenzen.} Abriebsarbeit übersteigt jeden Vorrat; Reihenfolge immer: reparieren, umbauen, ersetzen.

\begin{tabular}{p{3.6cm}p{5.0cm}p{5.0cm}}
\toprule
Grenze & Früherkennung & Maßnahme \\
\midrule
Nässe & beschlagene Innenhülle, kalter Handrücken & Trocknungsplan, Ersatzhülle bereithalten \\
Abrieb & sichtbare Fäden, dünner Fleck & Flicken vor dem Loch, 7.3 \\
Zeit & Satzkarte älter als 3 Monate ohne Eintrag & Bestandskontrolle, Tausch vorbereiten \\
\bottomrule
\end{tabular}
\end{konzept}

\begin{baustein}
\merk{Drei Lagen schlagen einen dicken Mantel: jede Lage einzeln nutzbar.} \\
\merk{Nasse Schutzhülle trocknen vor dem Feuer zerstört sie; trocknen im Wind.}
\end{baustein}

\section{Kapitel-Checkliste: Kleidung im Ernstfall}

\begin{checkliste}
\item Satzkarte je Person ausgefüllt (Vorlage A.11); alle drei Lagen vorhanden.
\item Basisschicht enthält keine Baumwolle als einzige Lage.
\item Schutzhülle hat die Nässeprobe bestanden; Basisschicht blieb trocken.
\item Beschaffungsplan je Person mit Weg und Datum eingetragen.
\item Scheuerstellen sind vorgeflickt, nicht abgewartet.
\item Fundregeln und Gemeingut-Regel aus Kapitel 1 bekannt.
\end{checkliste}

% =====================================================================
\chapter{Lagerorganisation: Tragen, Lagern, Nachtordnung}
% =====================================================================

\section{Konzept 9.1: Tragen: Lasten verteilen, Körper schonen}

\begin{konzept}{9.1 – Tragen: Lasten verteilen, Körper schonen}
\textbf{Definition.} Tragen heißt: Last nahe am Körper, auf beiden Schultern oder auf dem Becken, mit Gehschritt getragen. Grenzlasten, Faustwert: 15 kg Dauerlast für Erwachsene über 3 Stunden; darüber Verteilung auf mehrere Gänge.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Wiegeprobe: eine bekannte 15-kg-Last 3 Stunden tragen, Pausen protokollieren.
  \item Trageprobe des Packens: dreimal gleicher Inhalt, verschiedene Verteilungen, Muskelermüdung vergleichen.
  \item Prüfung der Behelfs-Trage aus Vorrat oder Astwerk (Übung C.13).
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Regeln gelten Stadt und Land gleich.
  \item Praxistauglichkeit: Tragehilfen ohne Nähen, aus Wickelwerk.
  \item Ehrlichkeit: Überschreiten der Dauerlast zahlt der Rücken zurück; Schäden kündigen sich nicht an.
\end{enumerate}

\textbf{Grenzen.} Kinder tragen Faustwert: 20 Prozent des Körpergewichts, maximal 5 kg. Keine Ausnahme.

\begin{tabular}{p{3.4cm}p{4.6cm}p{5.0cm}}
\toprule
Tragebehelf & Material & Ausführung, Faustwerte \\
\midrule
Schultertrage aus Planen & 1 m\textsuperscript{2} Plane, 4 Schnüre & Ecken einrollen, Körpermitte als Mulde, 2 Träger \\
Stangentrage & 1 Stange 150 cm, 2 Schnurbünde & Last mittig und festgebunden, zwei Träger \\
Kopftrage & Korb oder Reet mit Auflage & nur bis 8 kg, Gehweg ohne Hindernis \\
Tragegestell aus Astgabel & Y-Gabeln, Querast & Rückenpolster aus Stoff, min. 3 cm dick \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Richtig heben und tragen (jedes Mal).}
\begin{enumerate}
  \item Last einschätzen: über 15 kg? Teilen oder Hilfsträger holen.
  \item Mit den Beinen heben, Rücken gerade, Last an den Körper.
  \item Erst drehen, dann gehen; nie unter Last drehen.
  \item Pausen alle 30 Minuten, Last absetzen, nicht halten.
  \item Nach dem Tragen Rücken 5 Minuten bewegen, sonst Versteifung.
\end{enumerate}
\end{konzept}

\section{Konzept 9.2: Lagern: Vorräte gegen Nässe, Schädlinge, Diebstahl}

\begin{konzept}{9.2 – Lagern: Vorräte gegen Nässe, Schädlinge, Diebstahl}
\textbf{Definition.} Lagern heißt: Textil und Material trocken, hoch, geprüft lagern. Drei Gefahren: Nässe (verdirbt Faser und Füllung), Schädlinge (Nagetiere, Motten), Zugriff durch Dritte.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Feuchtekontrolle: 7-Tage-Rhythmus, Handprobe in jede Lagerkiste (Übung C.14).
  \item Schädlingskontrolle: Kotspuren, Fraßgänge, Federn und Haare am Lagerplatz.
  \item Zugangskontrolle: Verwahrung gegen unbefugten Zugriff geprüft, ohne Waffen.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: Lagerregeln decken beide Ausgangslagen; Stadt betont Zugriff, Land betont Schädlinge.
  \item Praxistauglichkeit: Regeln ohne Geräte durchführbar.
  \item Ehrlichkeit: jede Verwahrung ist überwindbar; Ziel ist Aufwandserhöhung, kein absoluter Schutz.
\end{enumerate}

\textbf{Grenzen.} Verderbware gehört nicht in Textillager; Lagerhaltung nach Band 2 gilt für Lebensmittel.

\begin{tabular}{p{3.2cm}p{4.6cm}p{4.6cm}}
\toprule
Gefahr & Stadt-Maßnahme & Land-Maßnahme \\
\midrule
Nässe & Regal 20 cm über Boden, Innenwand außenliegend & Trockenboden aus Rost, Kistendeckel \\
Nagetiere & Metallkisten, dichte Deckel, Glaskanten frei & aufgehängte Kisten, Gabelkette am Pfosten \\
Motten & Lavendel­lagen, Sonne alle 14 Tage & Wermut zwischen Wollsachen, Sonnenprobe \\
Zugriff & neutrale Behältnisse, keine Markierung nach außen & Lager verteilt, Kerngut im Erdreich \\
\bottomrule
\end{tabular}

\textbf{Anleitung: Lager einrichten (2 Stunden).}
\begin{enumerate}
  \item Wählen Sie einen trockenen, belüfteten Raum ohne Erdkontakt des Guts.
  \item Errichten Sie Böden aus Rundholz oder Paletten, 20 cm hoch.
  \item Sortieren Sie nach Kategorien: Textil, Füllgut, Werkzeug, Schnüre, Nähset.
  \item Verschließen Sie jede Kategorie separat; Textil in Stoffbeutel, nie in Plastik ohne Lüftungsloch.
  \item Hängen Sie den 7-Tage-Prüfplan aus (Vorlage A.12) und haken Sie jede Prüfung ab.
  \item Führen Sie ein Lagerbuch: Zugang, Abgang, Zustand (Vorlage A.13).
\end{enumerate}
\end{konzept}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-9-1}
\caption{Abb. 9.1 – Lageraufbau: Boden, Kategorien, Prüfplan am Beispiel eines Lagerraums}
\end{figure}

\section{Konzept 9.3: Nachtordnung: Ablauf vor und nach dem Schlafen}

\begin{konzept}{9.3 – Nachtordnung: Ablauf vor und nach dem Schlafen}
\textbf{Definition.} Nachtordnung ist ein fester, immer gleicher Ablauf: Trocknen, Ordnen, Prüfen, Wecken. Sie verhindert den häufigsten Fehler: nass und unaufgeräumt schlafen gehen.

\textbf{Dreifache Prüfung.}
\begin{enumerate}
  \item Ablauf 14 Nächte in Folge ausgeführt, Durchführungszeit gestoppt (Übung C.15).
  \item Nässekontrolle: morgens getrocknete Textilien bleiben trocken in der Nachtordnung.
  \item Probealarm: Ablauf bei unterbrochener Nacht (Geräusch, Wetterwechsel) ohne Licht.
\end{enumerate}

\textbf{Dreifache Bewertung.}
\begin{enumerate}
  \item Stimmigkeit: jede Station greift ein Ergebnis der Kapitel 6 bis 8 auf.
  \item Praxistauglichkeit: unter 20 Minuten für eine Person.
  \item Ehrlichkeit: bei mehreren Personen verdoppelt sich die Zeit; Ordnungsführung vorher festlegen.
\end{enumerate}

\textbf{Grenzen.} Nachtordnung schlägt nicht Extremwetter: bei Wetterwechsel mitten in der Nacht gilt Alarmplan Vorlage A.14, nicht der Standardablauf.

\textbf{Nachtordnung: Abend-Checkliste (immer in dieser Reihenfolge).}
\begin{enumerate}
  \item Füllmaterial des Schlafplatzes aufschütteln, Setzstellen auffüllen (6.1).
  \item Nasse Kleidung ausziehen, aufhängen, trockene Basisschicht anziehen (8.1).
  \item Schutzhülle im Wind aufhängen, nicht an der Feuerstelle (8.3).
  \item Nähset, Feuerzeug, Wasser auf festen Platz am Kopfende (9.2).
  \item Türvorhang dichten, Lüftungsöffnung prüfen (3.2, 5.2).
  \item Werkzeug vom Schlafplatz fern, mindestens eine Armlänge.
  \item Faustprobe am Schlafplatz, vier Ecken (6.3).
\end{enumerate}

\textbf{Nachtordnung: Morgen-Checkliste.}
\begin{enumerate}
  \item Schlafhülle offen 15 Minuten lüften, Decke über die Stange.
  2. Füllmaterial wenden, Feuchte fühlen; nass heißt tauschen.
  \item Kleidung des Tages anziehen erst nach Bewegung, 5 Minuten.
  \item Wasser und Feuerzeug zurück an den Tagesplatz.
  \item Lagerbuch-Eintrag: Nachttemperatur-Gefühl, Feuchte, Schäden (A.13).
\end{enumerate}
\end{konzept}

\begin{baustein}
\merk{Nass ins Bett heißt kalt aufwachen: erst trocknen, dann schlafen.} \\
\merk{Alles hat einen festen Platz; im Dunkeln greift die Hand ohne Licht.} \\
\merk{20 Minuten Abendordnung schützen die ganze Nacht.}
\end{baustein}

\section{Kapitel-Checkliste: Lagerorganisation}

\begin{checkliste}
\item Tragelasten liegen unter 15 kg Dauerlast; Kinder unter 5 kg.
\item Tragebehelf ist gebaut und geprüft; Hebel-Regeln bekannt.
\item Lager hat Bodenabstand 20 cm, Kategoriekisten, Prüfplan A.12.
\item 7-Tage-Prüfung läuft; letzte Prüfung ist abgehakt.
\item Lagerbuch geführt; Zugang und Abgang je Vorrat eingetragen.
\item Nachtordnung in 20 Minuten ohne Licht durchführbar.
\item Alarmplan Vorlage A.14 liegt griffbereit am Kopfende.
\end{checkliste}
